import{bonusCherries}from'./bonus-decor.js';
import{connectedTerrain}from'./terrain.js';import{mapFingerprint}from'./world-decor.js';
// Only native bread tiles receive bread paint; fruit, glass and leaf ramps retain their own colors.
export const BREAD_TILES=new Set([2,5,481,482,483,484,491,492,493,494,495,496,497,498,499,500,501,503,504,505,506,507,508,509,510,511,522,524,525,529,530]);
export function isBreadTile(level,v){return BREAD_TILES.has(v)&&(v>=256||level.id==='B');}
export function banquetSource(assets,level,map){const width=4096,height=level.height*16,source=new Uint8Array(width*height),bread=new Uint8Array(source.length),tops=new Int16Array(source.length).fill(-1),bottoms=new Int16Array(source.length).fill(-1);
 for(let ty=0;ty<level.height;ty++)for(let tx=0;tx<256;tx++){const v=level.lookup[map[ty*256+tx]];if(v===undefined||v===256||v===65535)continue;const bank=v<256?assets.tiles[level.id]:assets.union,off=(v<256?v:v-256)*256;for(let y=0;y<16;y++){const row=(ty*16+y)*width+tx*16;source.set(bank.subarray(off+y*16,off+y*16+16),row);if(isBreadTile(level,v))for(let x=0;x<16;x++)bread[row+x]=source[row+x]?1:0;}}
 // Group semantic bread cells first; tiny edge columns must not each restart
 // the entire bread/lettuce texture. Include separated lettuce pixels in each object.
 const pending=new Set();map.forEach((t,i)=>{if(isBreadTile(level,level.lookup[t]))pending.add(i);});
 while(pending.size){const queue=[pending.values().next().value];pending.delete(queue[0]);for(let n=0;n<queue.length;n++){const at=queue[n],tx=at%256,ty=at>>8;for(let yy=ty-1;yy<=ty+1;yy++)for(let xx=tx-1;xx<=tx+1;xx++){const k=yy*256+xx;if(xx>=0&&xx<256&&pending.has(k)){pending.delete(k);queue.push(k);}}}
  let top=height,bottom=-1;for(const at of queue)for(let y=0;y<16;y++)for(let x=0;x<16;x++){const p=((at>>8)*16+y)*width+(at%256)*16+x;if(bread[p]){top=Math.min(top,(at>>8)*16+y);bottom=Math.max(bottom,(at>>8)*16+y);}}
  for(const at of queue)for(let y=0;y<16;y++)for(let x=0;x<16;x++){const p=((at>>8)*16+y)*width+(at%256)*16+x;if(bread[p]){tops[p]=top;bottoms[p]=bottom;}}
 }return{width,height,source,bread,tops,bottoms};}
export function banquetSampler(world,material,ox,oy){const out=new Float32Array(4);return(x,y)=>{const wx=ox*4+x,wy=oy*4+y,nx=Math.max(0,Math.min(world.width-1,Math.floor(wx/4))),ny=Math.max(0,Math.min(world.height-1,Math.floor(wy/4))),p=ny*world.width+nx,top=world.tops[p],bottom=world.bottoms[p];if(top<0)return null;const u=((wx%material.width)+material.width)%material.width,v=Math.max(0,Math.min(material.height-1,Math.floor((wy/4-top+.5)/(bottom-top+1)*material.height))),q=(v*material.width+Math.floor(u))*4;for(let k=0;k<3;k++)out[k]=material.data[q+k];out[3]=material.data[q+3]/255;return out;};}
export class BanquetTerrain{
 constructor(){this.chunks=new Map();}
 draw(hd,assets,level,map,cx,cy){const fingerprint=mapFingerprint(map);if(this.map!==map||this.fingerprint!==fingerprint){this.map=map;this.fingerprint=fingerprint;this.world=banquetSource(assets,level,map);this.decor=hd.pack.manifest.bonusDecor?.cherries?bonusCherries(level,map):[];for(const o of this.decor)for(const at of o.cells)for(let y=0;y<16;y++)this.world.source.fill(0,((at>>8)*16+y)*4096+(at%256)*16,((at>>8)*16+y)*4096+(at%256+1)*16);this.chunks.clear();}const w=this.world,material=hd.materialImage(hd.pack.manifest.banquetMaterial),size=64,halo=16,extent=96;
 hd.connectedLayer(cx,cy,(c,b)=>{for(let gy=b.y0;gy<=b.y1;gy++)for(let gx=b.x0;gx<=b.x1;gx++){const key=gx+':'+gy,ox=gx*size,oy=gy*size;let image=this.chunks.get(key);if(!image){const src=new Uint8Array(extent*extent);for(let y=0;y<extent;y++)for(let x=0;x<extent;x++){const wx=ox+x-halo,wy=oy+y-halo;if(wx>=0&&wx<w.width&&wy>=0&&wy<w.height)src[y*extent+x]=w.source[wy*w.width+wx];}const rgba=connectedTerrain(src,extent,extent,hd.palette,banquetSampler(w,material,ox-halo,oy-halo),{paintColor:true,paintAlpha:true});image=document.createElement('canvas');image.width=image.height=256;image.getContext('2d').putImageData(new ImageData(rgba,384,384),-64,-64);this.chunks.set(key,image);}c.drawImage(image,ox*4,oy*4);}});for(const o of this.decor)if(o.x+80>=cx&&o.x<=cx+320&&o.y+96>=cy&&o.y<=cy+176)hd.atlas(hd.pack.manifest.bonusDecor.cherries,o.x-cx,o.y-cy);while(this.chunks.size>96)this.chunks.delete(this.chunks.keys().next().value);return true;
 }
}
